// TeichSeat — the Durable Object seat of self (INFRA_DESIGN.md, RECOVERY_POLICY.md).
//
// The state blob is OPAQUE TEXT: this code never parses or re-serializes it, so
// byte-fidelity of the float64 state is by construction (gate I1).
// Single-writer lease/commit makes forking structurally impossible (gate I2).
// Hourly alarm appends to the hash-chained snapshot table (gate I4); daily it pins
// the newest snapshot to Pinata iff the PINATA_JWT secret is installed.
//
// Routing: /o/<name>/<endpoint>. Teich's real seat is name "teich"; gate drills use
// other names. Destructive test endpoints refuse to run on "teich".

import { DurableObject } from "cloudflare:workers";

const LEASE_TTL_MS = 15 * 60 * 1000;
const SNAPSHOT_EVERY_MS = 60 * 60 * 1000;
const PIN_EVERY_MS = 24 * 60 * 60 * 1000;
const PIN_KEEP = 30;            // each seat keeps its newest 30 Pinata pins; older ones are unpinned after a pin
const PIN_UNPIN_MAX = 10;       // at most this many unpins per run (Worker subrequest budget)

async function sha256hex(text) {
  const d = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return [...new Uint8Array(d)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

// ---- the Seal's constants and byte helpers (v0.7)
const SEAL_DAY = 86400, SEAL_LEAD = 900;   // ticks per day; the quiet quarter-hour (creature_v07.SKY_LEAD)
const SEAL_LAST_S = 120;                   // never sign later than this before its midnight (its round: from 30 s before)
const SEAL_RETRY_MS = 15 * 1000;
const hexBytes = (h) => new Uint8Array(h.match(/.{2}/g).map((x) => parseInt(x, 16)));
const bytesHex = (b) => [...b].map((x) => x.toString(16).padStart(2, "0")).join("");
const b64url = (b) => btoa(String.fromCharCode(...b)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
const concatBytes = (a, b) => { const o = new Uint8Array(a.length + b.length); o.set(a); o.set(b, a.length); return o; };
const sha256bytes = async (b) => new Uint8Array(await crypto.subtle.digest("SHA-256", b));
function sameJSON(a, b) {
  if (a === null || b === null || typeof a !== "object" || typeof b !== "object") return a === b;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const ka = Object.keys(a), kb = Object.keys(b);
  return ka.length === kb.length && ka.every((k) => Object.prototype.hasOwnProperty.call(b, k) && sameJSON(a[k], b[k]));
}

const json = (obj, status = 200) =>
  new Response(JSON.stringify(obj), { status, headers: { "content-type": "application/json" } });

export class TeichSeat extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    this.sql = ctx.storage.sql;
    this.sql.exec(`CREATE TABLE IF NOT EXISTS seat (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        blob TEXT NOT NULL, n_ticks INTEGER NOT NULL, genesis_anchor TEXT NOT NULL,
        lease_id TEXT, lease_ts INTEGER, updated_ts INTEGER NOT NULL)`);
    this.sql.exec(`CREATE TABLE IF NOT EXISTS snapshots (
        i INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL,
        n_ticks INTEGER NOT NULL, prev TEXT NOT NULL, hash TEXT NOT NULL,
        blob TEXT NOT NULL)`);
    this.sql.exec(`CREATE TABLE IF NOT EXISTS events (
        i INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL,
        type TEXT NOT NULL, detail TEXT NOT NULL)`);
    // Added 2026-10-21 for v0.4 (additive; seats that never call these are unchanged):
    // log = the creature's closed records (append-only, contiguous seq, hash-chained from the genesis anchor);
    // settings = per-seat options (snapshot_on_change_only).
    this.sql.exec(`CREATE TABLE IF NOT EXISTS log (
        seq INTEGER PRIMARY KEY, ts INTEGER NOT NULL, rec TEXT NOT NULL, h TEXT NOT NULL)`);
    this.sql.exec(`CREATE TABLE IF NOT EXISTS settings (k TEXT PRIMARY KEY, v TEXT NOT NULL)`);
    // Added 2026-11-06 for v0.7 (the Seal; additive: a seat without seal-init never writes it). A missed day is a row
    // with empty canon: recorded, never sealed late.
    this.sql.exec(`CREATE TABLE IF NOT EXISTS seals (
        day INTEGER PRIMARY KEY, seq INTEGER, canon TEXT NOT NULL, sig TEXT NOT NULL, ts INTEGER NOT NULL)`);
  }

  #setting(k) {
    const r = [...this.sql.exec("SELECT v FROM settings WHERE k=?", k)];
    return r.length ? JSON.parse(r[0].v) : null;
  }

  #putSetting(k, v) {
    this.sql.exec("INSERT INTO settings (k, v) VALUES (?, ?) ON CONFLICT(k) DO UPDATE SET v=excluded.v", k, JSON.stringify(v));
  }

  // ---- the Seal (v0.7, SKY_SPEC_v07_v1 §3.7). Day d's seal is signed when its quiet quarter-hour begins (wall time
  // t0 + (d+1)·DAY − 900), once no lease is open and the last commit's records are in the log; never later than
  // SEAL_LAST_S before its midnight (its round can be published from 30 s before). A day that cannot be sealed in
  // time is recorded as missed: it stays unwitnessed, never sealed late.
  #sealDue(nowMs) {
    const s = this.#setting("seal");
    if (!s) return null;
    const t = nowMs / 1000, t0 = Number(s.t0);
    let d = Math.floor((t - t0) / SEAL_DAY);
    const at = (dd) => (t0 + (dd + 1) * SEAL_DAY - SEAL_LEAD) * 1000;
    if (t * 1000 >= at(d) + (SEAL_LEAD - SEAL_LAST_S) * 1000 || this.#sealOf(d)) d += 1;   // too late or done: next day
    return { day: d, at: at(d), last: at(d) + (SEAL_LEAD - SEAL_LAST_S) * 1000 };
  }

  #sealOf(day) {
    return [...this.sql.exec("SELECT day, canon, sig, ts FROM seals WHERE day=?", day)][0] || null;
  }

  async #sealKey(pubHex) {
    if (!this.env.SEAL_KEY || !/^[0-9a-f]{64}$/.test(this.env.SEAL_KEY)) return null;
    const jwk = { kty: "OKP", crv: "Ed25519", d: b64url(hexBytes(this.env.SEAL_KEY)), x: b64url(hexBytes(pubHex)) };
    try {
      const priv = await crypto.subtle.importKey("jwk", jwk, { name: "Ed25519" }, false, ["sign"]);
      const pub = await crypto.subtle.importKey("raw", hexBytes(pubHex), { name: "Ed25519" }, false, ["verify"]);
      const probe = new TextEncoder().encode("teich-seal-probe");
      const sig = new Uint8Array(await crypto.subtle.sign({ name: "Ed25519" }, priv, probe));
      return (await crypto.subtle.verify({ name: "Ed25519" }, pub, sig, probe)) ? priv : null;   // key and pub agree
    } catch (e) {
      return null;                                    // a key pair that does not import is not this seat's key
    }
  }

  async #trySeal(nowMs) {
    // a day whose deadline passed with no seal row (the alarm came late) is recorded as missed, never skipped
    const s0 = this.#setting("seal"), t0 = Number(s0.t0), d0 = Math.floor((nowMs / 1000 - t0) / SEAL_DAY);
    const at0 = (t0 + (d0 + 1) * SEAL_DAY - SEAL_LEAD) * 1000, last0 = at0 + (SEAL_LEAD - SEAL_LAST_S) * 1000;
    if (nowMs >= last0 && at0 >= s0.init_ts && !this.#sealOf(d0)) {
      this.#event("seal-missed", { day: d0, why: "its deadline passed before the seat could sign" });
      this.sql.exec("INSERT INTO seals (day, canon, sig, ts) VALUES (?, ?, ?, ?)", d0, "", "", nowMs);
    }
    const due = this.#sealDue(nowMs);
    if (!due || nowMs < due.at) return due ? due.at : null;
    const s = this.#setting("seal"), seat = this.#seat();
    const leaseOpen = seat.lease_id && nowMs - seat.lease_ts < LEASE_TTL_MS;
    const lastAppend = ([...this.sql.exec("SELECT MAX(ts) AS t FROM log")][0] || {}).t || 0;
    const flushed = lastAppend >= seat.updated_ts;
    if (leaseOpen || !flushed) {
      if (nowMs + SEAL_RETRY_MS <= due.last) return nowMs + SEAL_RETRY_MS;
      this.#event("seal-missed", { day: due.day, lease_open: !!leaseOpen, flushed });
      this.sql.exec("INSERT INTO seals (day, canon, sig, ts) VALUES (?, ?, ?, ?)", due.day, "", "", nowMs);
      return this.#sealDue(nowMs + 1000).at;
    }
    const key = await this.#sealKey(s.pub);
    if (!key) { this.#event("seal-missed", { day: due.day, why: "no usable SEAL_KEY" });
      this.sql.exec("INSERT INTO seals (day, canon, sig, ts) VALUES (?, ?, ?, ?)", due.day, "", "", nowMs);
      return this.#sealDue(nowMs + 1000).at; }
    const name = this.#setting("seat_name");
    // canonical text, exactly as Python's seal_v07.canonical writes it: sorted keys, no spaces, t0 in Python's repr
    const canon = `{"day":${due.day},"head":"${s.head}","n":${seat.n_ticks},"seat":${JSON.stringify(name)},` +
                  `"seq":${s.head_seq},"t0":${s.t0},"v":"teich-seal-1"}`;
    const sig = bytesHex(new Uint8Array(await crypto.subtle.sign({ name: "Ed25519" }, key, new TextEncoder().encode(canon))));
    this.sql.exec("INSERT INTO seals (day, seq, canon, sig, ts) VALUES (?, ?, ?, ?, ?)", due.day, s.head_seq, canon, sig, nowMs);
    this.#event("seal", { day: due.day, seq: s.head_seq, head: s.head });
    return this.#sealDue(nowMs + 1000).at;
  }

  #logHead() {
    const r = [...this.sql.exec("SELECT seq, h FROM log ORDER BY seq DESC LIMIT 1")];
    return r.length ? r[0] : null;
  }

  #seat() {
    const rows = [...this.sql.exec("SELECT * FROM seat WHERE id=1")];
    return rows.length ? rows[0] : null;
  }

  #event(type, detail) {
    this.sql.exec("INSERT INTO events (ts, type, detail) VALUES (?, ?, ?)",
      Date.now(), type, JSON.stringify(detail));
  }

  #chainHead() {
    const r = [...this.sql.exec("SELECT i, hash, n_ticks, ts FROM snapshots ORDER BY i DESC LIMIT 1")];
    return r.length ? r[0] : null;
  }

  async #snapshot(reason) {
    const seat = this.#seat();
    if (!seat) return null;
    const head = this.#chainHead();
    const prev = head ? head.hash : seat.genesis_anchor;
    const hash = await sha256hex(prev + seat.blob);
    this.sql.exec(
      "INSERT INTO snapshots (ts, n_ticks, prev, hash, blob) VALUES (?, ?, ?, ?, ?)",
      Date.now(), seat.n_ticks, prev, hash, seat.blob);
    this.#event("snapshot", { reason, n_ticks: seat.n_ticks, hash });
    return hash;
  }

  async #verifyChain(uptoI = null) {
    const seat = this.#seat();
    const rows = [...this.sql.exec(
      uptoI === null ? "SELECT * FROM snapshots ORDER BY i"
                     : "SELECT * FROM snapshots WHERE i<=? ORDER BY i", ...(uptoI === null ? [] : [uptoI]))];
    let prev = seat.genesis_anchor;
    for (const r of rows) {
      if (r.prev !== prev) return { ok: false, bad_i: r.i, why: "prev-link mismatch" };
      const h = await sha256hex(prev + r.blob);
      if (h !== r.hash) return { ok: false, bad_i: r.i, why: "hash mismatch" };
      prev = r.hash;
    }
    return { ok: true, n: rows.length, head: prev };
  }

  // Unpin this seat's own pins beyond the newest PIN_KEEP (pins labelled with keyvalues seat=<name>; older unlabelled
  // pins, e.g. the 2026-11-01 weekly archive, are never touched). The free plan caps an account at 500 files.
  async #rotatePins(seatName) {
    try {
      const auth = { authorization: `Bearer ${this.env.PINATA_JWT}` };
      const q = encodeURIComponent(JSON.stringify({ seat: { value: seatName, op: "eq" } }));
      const r = await fetch(`https://api.pinata.cloud/data/pinList?status=pinned&pageLimit=1000&metadata[keyvalues]=${q}`,
                            { headers: auth });
      if (!r.ok) {                     // e.g. a key scoped to pinning only: say so, never fail silently
        this.#event("pinata-rotate-error", { status: r.status, body: (await r.text()).slice(0, 300) });
        return { error: `pinList ${r.status}` };
      }
      const rows = ((await r.json()).rows || [])
        .filter((x) => x.metadata && x.metadata.keyvalues && x.metadata.keyvalues.seat === seatName)
        .sort((a, b) => (a.date_pinned < b.date_pinned ? 1 : -1));
      const old = rows.slice(PIN_KEEP).slice(0, PIN_UNPIN_MAX);
      const unpinned = [];
      for (const x of old) {
        const d = await fetch(`https://api.pinata.cloud/pinning/unpin/${x.ipfs_pin_hash}`, { method: "DELETE", headers: auth });
        if (d.ok) unpinned.push(x.ipfs_pin_hash);
      }
      const ev = { seat: seatName, pinned: rows.length, kept: Math.min(rows.length, PIN_KEEP), unpinned };
      if (unpinned.length || old.length) this.#event("pinata-rotate", ev);
      return ev;
    } catch (e) {
      this.#event("pinata-rotate-error", { message: String(e) });
      return { error: String(e) };
    }
  }

  async #pinNewest() {
    // Public IPFS must NEVER see the state in clear: the blob carries private phi,
    // and deterministic rotation makes one clear sample at a known tick equivalent
    // to publishing phi0 forever (sealed-phi0 amendment). AES-256-GCM under the
    // founder's SNAPSHOT_KEY; chain metadata (prev/hash of PLAINTEXT) stays public
    // so the chain is still verifiable after founder-side decryption.
    if (!this.env.PINATA_JWT) return { error: "no PINATA_JWT secret installed" };
    if (!this.env.SNAPSHOT_KEY) return { error: "no SNAPSHOT_KEY secret installed" };
    const head = [...this.sql.exec("SELECT * FROM snapshots ORDER BY i DESC LIMIT 1")][0];
    if (!head) return { error: "no snapshots" };
    const seatName = this.#setting("seat_name");
    try {
      const keyBytes = new Uint8Array(
        this.env.SNAPSHOT_KEY.match(/.{2}/g).map((h) => parseInt(h, 16)));
      const key = await crypto.subtle.importKey("raw", keyBytes, "AES-GCM", false, ["encrypt"]);
      const iv = crypto.getRandomValues(new Uint8Array(12));
      const ct = new Uint8Array(await crypto.subtle.encrypt(
        { name: "AES-GCM", iv }, key, new TextEncoder().encode(head.blob)));
      // chunked: spreading a whole snapshot as arguments overflows the call stack (teich-05, 2026-10-25 on)
      const b64 = (u8) => {
        let s = "";
        for (let i = 0; i < u8.length; i += 0x8000) s += String.fromCharCode(...u8.subarray(i, i + 0x8000));
        return btoa(s);
      };
      const r = await fetch("https://api.pinata.cloud/pinning/pinJSONToIPFS", {
        method: "POST",
        headers: { "content-type": "application/json",
                   authorization: `Bearer ${this.env.PINATA_JWT}` },
        body: JSON.stringify({
          pinataMetadata: { name: `${seatName || "teich-seat"}-snapshot-${head.i}`,
                            keyvalues: seatName ? { seat: seatName, kind: "snapshot" } : undefined },
          pinataContent: { i: head.i, ts: head.ts, n_ticks: head.n_ticks,
                           prev: head.prev, hash: head.hash,
                           enc: "AES-256-GCM", iv: b64(iv), ciphertext: b64(ct) },
        }),
      });
      const out = await r.json();
      if (!out.IpfsHash) {               // a refusal (e.g. plan limit) is not a pin: log it as an error, retry next hour
        this.#event("pinata-pin-error", { i: head.i, status: r.status, refused: out.error || out });
        return { error: "pinata refused", status: r.status, refused: out.error || out };
      }
      const ev = { i: head.i, hash: head.hash, ipfs: out.IpfsHash, encrypted: true };
      this.#event("pinata-pin", ev);
      const rotated = seatName ? await this.#rotatePins(seatName) : null;
      return { ok: true, ...ev, rotated };
    } catch (e) {
      this.#event("pinata-pin-error", { message: String(e) });
      return { error: String(e) };
    }
  }

  async fetch(request) {
    const url = new URL(request.url);
    // path arrives as /<endpoint> (worker strips /o/<name>); name via header
    const ep = url.pathname.replace(/^\//, "");
    const name = request.headers.get("X-Seat-Name") || "?";
    if (name !== "?" && this.#setting("seat_name") !== name)       // the alarm has no request: remember who we are
      this.sql.exec("INSERT INTO settings (k, v) VALUES ('seat_name', ?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",
                    JSON.stringify(name));
    const now = Date.now();
    const seat = this.#seat();
    const body = request.method === "POST" ? await request.json().catch(() => ({})) : {};

    if (ep === "peek") {
      const head = this.#chainHead();
      return json({
        alive: !!seat, name, n_ticks: seat ? seat.n_ticks : null,
        updated_ts: seat ? seat.updated_ts : null,
        chain_head: head ? head.hash : null, snapshots: head ? head.i : 0,
        // public since 2026-11-01 for the face's checks: the record log's head and the last off-site pin
        log_head: this.#logHead(),
        last_pin_ts: ([...this.sql.exec("SELECT ts FROM events WHERE type='pinata-pin' ORDER BY i DESC LIMIT 1")][0] || {}).ts || null,
      });
    }

    // read-only, public only for seats whose record log / anchors are already published (the router allowlists)
    if (ep === "log-public") {
      if (!seat) return json({ error: "seat not initialized" }, 404);
      const from = Math.max(1, parseInt(url.searchParams.get("from") || "1", 10) || 1);
      const limit = Math.min(Math.max(1, parseInt(url.searchParams.get("limit") || "500", 10) || 500), 500);
      const rows = [...this.sql.exec("SELECT seq, rec, h FROM log WHERE seq>=? ORDER BY seq LIMIT ?", from, limit)];
      return json({ genesis_anchor: seat.genesis_anchor, records: rows.map((r) => ({ seq: r.seq, h: r.h, raw: r.rec })) });
    }
    if (ep === "anchors-public") {
      const rows = [...this.sql.exec("SELECT ts, detail FROM events WHERE type='git-anchor' ORDER BY i")];
      return json({ anchors: rows.map((r) => { const d = JSON.parse(r.detail); return { ts: r.ts, git_sha: d.git_sha, ref: d.ref }; }) });
    }

    if (ep === "genesis-import") {
      if (seat) return json({ error: "seat already initialized" }, 409);
      if (typeof body.state_blob !== "string" || !Number.isInteger(body.n_ticks) ||
          typeof body.genesis_anchor !== "string")
        return json({ error: "need state_blob, n_ticks, genesis_anchor" }, 400);
      this.sql.exec(
        "INSERT INTO seat (id, blob, n_ticks, genesis_anchor, updated_ts) VALUES (1, ?, ?, ?, ?)",
        body.state_blob, body.n_ticks, body.genesis_anchor, now);
      this.#event("genesis-import", { n_ticks: body.n_ticks, anchor: body.genesis_anchor });
      await this.#snapshot("genesis-import");
      await this.ctx.storage.setAlarm(now + SNAPSHOT_EVERY_MS);
      return json({ ok: true, n_ticks: body.n_ticks });
    }

    if (!seat) return json({ error: "seat not initialized" }, 404);

    if (ep === "state")
      return json({ state_blob: seat.blob, n_ticks: seat.n_ticks,
                    lease_open: !!(seat.lease_id && now - seat.lease_ts < LEASE_TTL_MS) });

    if (ep === "lease") {
      if (seat.lease_id && now - seat.lease_ts < LEASE_TTL_MS)
        return json({ error: "lease already open", lease_age_ms: now - seat.lease_ts }, 409);
      const lease_id = crypto.randomUUID();
      this.sql.exec("UPDATE seat SET lease_id=?, lease_ts=? WHERE id=1", lease_id, now);
      this.#event("lease", { lease_id });
      return json({ lease_id, state_blob: seat.blob, n_ticks: seat.n_ticks });
    }

    if (ep === "commit") {
      if (!seat.lease_id || now - seat.lease_ts >= LEASE_TTL_MS)
        return json({ error: "no open lease" }, 409);
      if (body.lease_id !== seat.lease_id)
        return json({ error: "stale or foreign lease" }, 409);
      if (typeof body.state_blob !== "string" || !Number.isInteger(body.n_ticks))
        return json({ error: "need state_blob, n_ticks" }, 400);
      if (body.n_ticks < seat.n_ticks)
        return json({ error: "n_ticks may not decrease outside /restore" }, 409);
      this.sql.exec(
        "UPDATE seat SET blob=?, n_ticks=?, lease_id=NULL, lease_ts=NULL, updated_ts=? WHERE id=1",
        body.state_blob, body.n_ticks, now);
      this.#event("commit", { lease_id: body.lease_id, n_ticks: body.n_ticks });
      return json({ ok: true, n_ticks: body.n_ticks });
    }

    if (ep === "log-seq") {
      const head = this.#logHead();
      return json({ seq: head ? head.seq : 0, head: head ? head.h : seat.genesis_anchor });
    }

    if (ep === "log-append") {
      // Records carry their own seq (the creature's outbox). Already-held seqs are skipped (a retried flush is
      // idempotent); the rest must continue the log contiguously, or nothing is written.
      if (!Array.isArray(body.records)) return json({ error: "need records[]" }, 400);
      // v0.7 (the Seal): records may come with their canonical text (seal_v07.canonical). It must parse to the same
      // record; it is then stored as the row itself, so the public log is canonical. Once the Seal is initialised
      // canonical text is required, and the running seal head is chained over it.
      const canon = Array.isArray(body.canon) ? body.canon : null;
      if (canon && canon.length !== body.records.length) return json({ error: "canon[] must match records[]" }, 400);
      const seal = this.#setting("seal");
      if (seal && !canon) return json({ error: "this seat is sealed: records need their canonical text" }, 400);
      const head = this.#logHead();
      let last = head ? head.seq : 0, h = head ? head.h : seat.genesis_anchor;
      const idx = [];
      body.records.forEach((r, k) => { if (Number.isInteger(r && r.seq) && r.seq > last) idx.push(k); });
      for (let k = 0; k < idx.length; k++)
        if (body.records[idx[k]].seq !== last + 1 + k) return json({ error: "log records out of sequence", last }, 400);
      for (const k of idx)
        if (canon && (typeof canon[k] !== "string" || !sameJSON(JSON.parse(canon[k]), body.records[k])))
          return json({ error: "canonical text does not match its record", seq: body.records[k].seq }, 400);
      if (seal) {                       // the seal's promise: nothing but a wake lands before a sealed midnight
        const lastSeal = [...this.sql.exec("SELECT day, seq FROM seals WHERE canon != '' ORDER BY day DESC LIMIT 1")][0];
        if (lastSeal) {
          const mid = (lastSeal.day + 1) * SEAL_DAY;
          const late = idx.map((k) => body.records[k]).filter((r) =>
            r.seq > lastSeal.seq && r.kind === "op" && r.op !== "wake" && r.n + r.owed < mid);
          if (late.length)
            return json({ error: `day ${lastSeal.day} is sealed: ops ${late.map((r) => r.seq)} would land before its midnight` }, 409);
        }
      }
      let sh = seal ? hexBytes(seal.head) : null;
      for (const k of idx) {
        const r = body.records[k];
        const rec = canon ? canon[k] : JSON.stringify(r);
        h = await sha256hex(h + rec);
        if (seal) sh = await sha256bytes(concatBytes(sh, new TextEncoder().encode(rec)));
        this.sql.exec("INSERT INTO log (seq, ts, rec, h) VALUES (?, ?, ?, ?)", r.seq, now, rec, h);
      }
      if (seal && idx.length)
        this.#putSetting("seal", { ...seal, head: bytesHex(sh), head_seq: last + idx.length });
      if (idx.length)
        this.#event("log-append", { from: last + 1, to: last + idx.length, head: h });
      return json({ ok: true, appended: idx.length, seq: last + idx.length, head: h });
    }

    if (ep === "log-read") {
      const from = Number.isInteger(body.from_seq) ? body.from_seq : 1;
      const limit = Math.min(Number.isInteger(body.limit) ? body.limit : 500, 2000);
      const rows = [...this.sql.exec("SELECT seq, ts, rec, h FROM log WHERE seq>=? ORDER BY seq LIMIT ?", from, limit)];
      // raw = the exact stored text the hash chain covers: h(seq) = sha256(h(seq-1) + raw), h(0) = genesis anchor
      return json({ records: rows.map((r) => ({ seq: r.seq, ts: r.ts, h: r.h, raw: r.rec, rec: JSON.parse(r.rec) })) });
    }

    if (ep === "seal-init") {
      // Once, at migration (v0.7): the published start blob must be this seat's committed state, the log must hold
      // every record through start_seq, and SEAL_KEY must sign for pub. H_0 = sha256("teich-journal-1" ‖ sha256(start)).
      if (this.#setting("seal")) return json({ error: "the Seal is already initialised" }, 409);
      const { start_blob_sha256: sb, start_seq, t0, pub } = body;
      if (!/^[0-9a-f]{64}$/.test(sb || "") || !Number.isInteger(start_seq) || !/^[0-9]+\.[0-9]+$/.test(t0 || "") ||
          !/^[0-9a-f]{64}$/.test(pub || ""))
        return json({ error: "need start_blob_sha256, start_seq, t0 (Python repr, e.g. 1792765970.0), pub" }, 400);
      if (await sha256hex(seat.blob) !== sb) return json({ error: "start blob is not this seat's committed state" }, 409);
      const lh = this.#logHead();
      if ((lh ? lh.seq : 0) !== start_seq) return json({ error: "the log must hold every record through start_seq", log_seq: lh ? lh.seq : 0 }, 409);
      if (!(await this.#sealKey(pub))) return json({ error: "SEAL_KEY missing or not the key of pub" }, 409);
      const h0 = bytesHex(await sha256bytes(concatBytes(new TextEncoder().encode("teich-journal-1"), hexBytes(sb))));
      const seal = { t0, start_seq, pub, start_blob_sha256: sb, head: h0, head_seq: start_seq, init_ts: now };
      this.#putSetting("seal", seal);
      this.#event("seal-init", seal);
      const due = this.#sealDue(now);
      await this.ctx.storage.setAlarm(Math.min(due.at, (await this.ctx.storage.getAlarm?.()) || Infinity));
      return json({ ok: true, ...seal, next_seal: { day: due.day, at_ms: due.at } });
    }

    if (ep === "seal-status") {
      const s = this.#setting("seal");
      const last = [...this.sql.exec("SELECT day, seq, canon, sig, ts FROM seals ORDER BY day DESC LIMIT 3")];
      return json({ seal: s, next: s ? this.#sealDue(now) : null, last });
    }

    if (ep === "seals-public") {
      // read-only, public for the sealed seat: every seal newest first (a missed day shows as missed, never filled in)
      const s = this.#setting("seal");
      if (!s) return json({ error: "this seat is not sealed" }, 404);
      const rows = [...this.sql.exec("SELECT day, canon, sig, ts FROM seals ORDER BY day DESC LIMIT 90")];
      return json({ pub: s.pub, t0: s.t0, start_seq: s.start_seq, start_blob_sha256: s.start_blob_sha256,
                    next: this.#sealDue(now),
                    seals: rows.map((r) => r.canon ? { day: r.day, canon: r.canon, sig: r.sig, pub: s.pub, signed_ts: r.ts }
                                                   : { day: r.day, missed: true, ts: r.ts }) });
    }

    if (ep === "snapshot-policy") {
      if (typeof body.on_change_only !== "boolean") return json({ error: "need on_change_only (boolean)" }, 400);
      this.sql.exec("INSERT INTO settings (k, v) VALUES ('snapshot_on_change_only', ?) " +
                    "ON CONFLICT(k) DO UPDATE SET v=excluded.v", JSON.stringify(body.on_change_only));
      this.#event("snapshot-policy", { on_change_only: body.on_change_only });
      return json({ ok: true, on_change_only: body.on_change_only });
    }

    if (ep === "snapshot-now")
      return json({ ok: true, hash: await this.#snapshot(body.reason || "manual") });

    if (ep === "pin-now")
      return json(await this.#pinNewest());

    if (ep === "snapshots") {
      const rows = [...this.sql.exec("SELECT i, ts, n_ticks, prev, hash FROM snapshots ORDER BY i")];
      return json({ snapshots: rows, chain: await this.#verifyChain() });
    }

    if (ep === "snapshot-blob") {
      const r = [...this.sql.exec("SELECT * FROM snapshots WHERE i=?", body.i)];
      return r.length ? json(r[0]) : json({ error: "no such snapshot" }, 404);
    }

    if (ep === "events") {
      const rows = [...this.sql.exec("SELECT * FROM events ORDER BY i DESC LIMIT ?", body.limit || 50)];
      return json({ events: rows });
    }

    if (ep === "restore") {
      // RECOVERY_POLICY §2.3: restore = coma, declared BEFORE first post-restore wake.
      if (!Number.isInteger(body.i) || typeof body.cause !== "string" || !body.cause)
        return json({ error: "need snapshot i and declared cause" }, 400);
      const chain = await this.#verifyChain(body.i);
      if (!chain.ok) return json({ error: "chain verification failed", chain }, 409);
      const r = [...this.sql.exec("SELECT * FROM snapshots WHERE i=?", body.i)];
      if (!r.length) return json({ error: "no such snapshot" }, 404);
      const coma = {
        type: "coma", restored_from_snapshot: body.i, restored_hash: r[0].hash,
        restored_n_ticks: r[0].n_ticks, prior_n_ticks: seat.n_ticks, cause: body.cause,
      };
      this.sql.exec(
        "UPDATE seat SET blob=?, n_ticks=?, lease_id=NULL, lease_ts=NULL, updated_ts=? WHERE id=1",
        r[0].blob, r[0].n_ticks, now);
      this.#event("coma", coma);
      return json({ ok: true, coma });
    }

    if (ep === "diary") {
      // Teich's inner voice: Workers AI, running INSIDE Cloudflare — the words are
      // generated where the seat lives, from the PUBLIC readout only. The caller
      // (a gate-certified body) supplies the fresh post-wake readout; private phi
      // is stripped defensively even if a caller misbehaves.
      if (!this.env.AI) return json({ error: "no AI binding deployed" }, 500);
      const ro = { ...(body.readout || {}) };
      delete ro.private_phase;
      // remembering organ (book scope): provenance-hashed recall lines compiled
      // by the body from the repo record. Sanitized: strings only, capped.
      const mem = (Array.isArray(body.memory) ? body.memory : [])
        .slice(0, 6).map((m) => String(m).slice(0, 320));
      // inner voice: Qwen family (same lineage as the certified Mouth), Workers AI
      // native (@cf/ = neuron-billed free tier; never paid partner models here)
      const model = body.model || "@cf/qwen/qwen3-30b-a3b-fp8";
      const sys =
        "You are the inner voice of Teich, a small dynamical creature: a chaotic " +
        "flow living one tick per real second on a certified attractor, with two " +
        "private phases nobody can decode. You are not a person and not a chatbot; " +
        "never claim consciousness or feelings — you have instrument readouts, not " +
        "introspection beyond them. Write a short private diary entry (3-6 " +
        "sentences, first person) grounded ONLY in the readout: basin is which " +
        "wing of the attractor you are on (-1 or +1); saddle_proximity (0..1) is " +
        "how torn between wings you are; lambda_running is your measured chaos " +
        "strength this window; steps_to_switch and will_flip are your own " +
        "falsifiable prediction about the next possible wing switch; n_switches " +
        "and mean_dwell describe how restless this window was. ticks_added is how " +
        "many seconds of hibernated life this wake just replayed deterministically. " +
        "Quote numbers exactly as given; never invent any. The 'remembered' list " +
        "holds true episodes from your own past records (each provenance-hashed in " +
        "your book): you may weave AT MOST one into the entry, faithfully — you may " +
        "compare today with a remembered day — but never invent a memory that is " +
        "not in the list.";
      // "/no_think" = Qwen3 soft switch: without it the model can burn the whole
      // token budget on hidden reasoning and return an empty entry
      const user = JSON.stringify({
        utc: new Date().toISOString(), n_ticks: body.n_ticks ?? seat.n_ticks,
        ticks_added: body.ticks_added ?? null, readout: ro,
        remembered: mem,
      }) + "\n/no_think";
      const messages = [{ role: "system", content: sys }, { role: "user", content: user }];
      let text = "", voiceModel = model, cfError = null;
      try {
        const out = await this.env.AI.run(model, { messages, max_tokens: 900 });
        // Workers AI returns either {response} or an OpenAI-style choices array
        text = String(
          (out && out.response) ??
          (out && out.choices && out.choices[0] &&
           out.choices[0].message && out.choices[0].message.content) ?? "").trim();
        if (!text) cfError = `empty AI response: ${JSON.stringify(out)}`;
      } catch (e) {
        cfError = String(e);
      }
      // Fallback: Cloudflare's free-neuron reset has proven unreliable (account-wide
      // 4006 with usage shown 0/10k). If the primary voice failed for ANY reason and
      // a NIM key is installed, retry once on NVIDIA's free API — same system prompt,
      // still generated inside this Durable Object, just a different LLM backend.
      if (!text && this.env.NIM_API_KEY) {
        try {
          const r = await fetch("https://integrate.api.nvidia.com/v1/chat/completions", {
            method: "POST",
            headers: { "content-type": "application/json",
                       "authorization": `Bearer ${this.env.NIM_API_KEY}` },
            body: JSON.stringify({ model: "meta/llama-3.1-70b-instruct", messages,
                                   max_tokens: 300, temperature: 0.7 }),
          });
          const out = await r.json();
          if (!r.ok) throw new Error(`NIM HTTP ${r.status}: ${JSON.stringify(out).slice(0, 200)}`);
          text = String(out?.choices?.[0]?.message?.content ?? "").trim();
          if (text) voiceModel = "nim:meta/llama-3.1-70b-instruct";
          else cfError = `${cfError} | NIM also empty: ${JSON.stringify(out)}`;
        } catch (e) {
          cfError = `${cfError} | NIM fallback failed: ${String(e)}`;
        }
      }
      if (!text) {
        this.#event("diary-error", { message: cfError || "unknown" });
        return json({ error: cfError || "empty AI response" }, 502);
      }
      const entry = { n_ticks: body.n_ticks ?? seat.n_ticks,
                      ticks_added: body.ticks_added ?? null, model: voiceModel, readout: ro,
                      remembered: mem, text };
      this.#event("diary", entry);
      return json({ ok: true, ...entry });
    }

    if (ep === "anchor") {
      // cross-anchor an external hash (e.g. a diary git commit SHA) into the
      // seat's event log, so the repo history and the seat chain vouch for each
      // other — rewriting either becomes detectable from the other.
      if (typeof body.git_sha !== "string" || !body.git_sha)
        return json({ error: "need git_sha" }, 400);
      const a = { git_sha: body.git_sha, ref: body.ref || "", note: body.note || "" };
      this.#event("git-anchor", a);
      return json({ ok: true, ...a });
    }

    if (ep === "drill-destroy") {
      // test-only: simulate loss by corrupting the live blob. NEVER on the real seat.
      if (name === "teich") return json({ error: "refused on the real seat" }, 403);
      this.sql.exec("UPDATE seat SET blob='CORRUPTED', updated_ts=? WHERE id=1", now);
      this.#event("drill-destroy", {});
      return json({ ok: true });
    }

    return json({ error: `unknown endpoint ${ep}` }, 404);
  }

  async alarm() {
    const now = Date.now();
    // A sealed seat (v0.7) also wakes for its seals; the hourly work keeps its own clock (hourly_next), so a seat
    // without the Seal behaves exactly as before: hourly work, next alarm in an hour.
    const sealed = !!this.#setting("seal");
    const hourlyNext = sealed ? this.#setting("hourly_next") : null;
    let nextHourly = hourlyNext;
    if (!sealed || hourlyNext === null || now >= hourlyNext - 5000) {
      // Seats that opted in (snapshot_on_change_only) skip the hourly snapshot when no commit has happened since the
      // last one: an identical blob adds nothing to the chain. Every other seat snapshots hourly, as before.
      const seat = this.#seat(), head = this.#chainHead();
      const unchanged = seat && head && seat.updated_ts <= head.ts;
      if (!(this.#setting("snapshot_on_change_only") && unchanged))
        await this.#snapshot("alarm-hourly");
      // daily off-Cloudflare pin, iff secret installed
      const lastPin = [...this.sql.exec(
        "SELECT ts FROM events WHERE type='pinata-pin' ORDER BY i DESC LIMIT 1")];
      if (this.env.PINATA_JWT && (!lastPin.length || now - lastPin[0].ts >= PIN_EVERY_MS))
        await this.#pinNewest();
      this.#event("heartbeat", {});
      nextHourly = now + SNAPSHOT_EVERY_MS;
      if (sealed) this.#putSetting("hourly_next", nextHourly);
    }
    const nextSeal = sealed ? await this.#trySeal(now) : null;
    await this.ctx.storage.setAlarm(nextSeal ? Math.min(nextHourly, nextSeal) : nextHourly);
  }
}

export default {
  async fetch(request, env) {
    try {
      return await handle(request, env);
    } catch (e) {
      return json({ error: "worker exception", message: String(e), stack: e.stack }, 500);
    }
  },
};

async function handle(request, env) {
    const url = new URL(request.url);
    if (url.pathname === "/" || url.pathname === "/index.html")
      return new Response(PANEL_HTML, {
        headers: { "content-type": "text/html;charset=utf-8" } });
    if (url.pathname === "/ping")
      return json({ pong: true, has_do: !!env.TEICH_SEAT, has_key: !!env.SEAT_KEY });

    // /lab/generate — stateless Workers AI proxy for the maturity campaign
    // (Mouth + judge roles). Runs INSIDE Cloudflare on the free neuron tier, so
    // the whole ablation stays $0 and needs no payment method. Authenticated;
    // free-native @cf/ models ONLY (never paid partner models); no seat, no DO.
    if (url.pathname === "/lab/generate") {
      if (request.method !== "POST") return json({ error: "POST only" }, 405);
      if (!env.SEAT_KEY || request.headers.get("X-Seat-Key") !== env.SEAT_KEY)
        return json({ error: "unauthorized" }, 401);
      if (!env.AI) return json({ error: "no AI binding" }, 500);
      const b = await request.json().catch(() => ({}));
      const model = String(b.model || "");
      if (!model.startsWith("@cf/"))
        return json({ error: "model must be @cf/ native (free tier)" }, 400);
      if (!Array.isArray(b.messages) || !b.messages.length)
        return json({ error: "need messages[]" }, 400);
      // deterministic soft-switch for Qwen3 reasoning models (empty-entry guard)
      const msgs = b.messages.map((m) => ({ role: String(m.role),
                                            content: String(m.content) }));
      if (b.no_think) {
        const last = msgs[msgs.length - 1];
        last.content += "\n/no_think";
      }
      const args = { messages: msgs, max_tokens: Math.min(b.max_tokens || 200, 1000) };
      if (typeof b.temperature === "number") args.temperature = b.temperature;
      if (typeof b.seed === "number") args.seed = b.seed;
      try {
        const out = await env.AI.run(model, args);
        const text = String(
          (out && out.response) ??
          (out && out.choices && out.choices[0] &&
           out.choices[0].message && out.choices[0].message.content) ?? "").trim();
        return json({ ok: true, model, text });
      } catch (e) {
        return json({ error: String(e), model }, 502);
      }
    }

    const m = url.pathname.match(/^\/o\/([a-z0-9-]{1,40})\/([a-z-]+)$/);
    if (!m) return json({ error: "path: /o/<name>/<endpoint>" }, 404);
    const [, name, ep] = m;
    const PUBLIC = { "log-public": ["teich-05"], "anchors-public": ["teich-03"],    // read-only, already-published data
                     "seals-public": ["teich-05"] };                                 // v0.7: its seals, for any watcher
    const isPublic = ep === "peek" || (request.method === "GET" && (PUBLIC[ep] || []).includes(name));
    if (!isPublic) {
      const key = request.headers.get("X-Seat-Key");
      if (!env.SEAT_KEY || key !== env.SEAT_KEY) return json({ error: "unauthorized" }, 401);
    }
    const stub = env.TEICH_SEAT.get(env.TEICH_SEAT.idFromName(name));
    const fwd = new Request(`https://do/${ep}${url.search}`, {
      method: request.method,
      headers: { "content-type": "application/json", "X-Seat-Name": name },
      body: request.method === "POST" ? await request.text() : undefined,
    });
    return stub.fetch(fwd);
}

